 export const InfoPopover = ({ label, title, children }: InfoPopoverProps) => {
   const popoverId = useId();
   const popoverRef = useRef<HTMLSpanElement | null>(null);
+  const triggerRef = useRef<HTMLButtonElement | null>(null);
